const b = $input.first().json.body ?? $input.first().json;
const customer = typeof b.customer === 'string' ? b.customer.trim().slice(0,100) : '';
const message = typeof b.message === 'string' ? b.message.trim().slice(0,4000) : '';
const source = typeof b.source === 'string' ? b.source.trim().slice(0,40) : 'web';
const requestId = typeof b.request_id === 'string' ? b.request_id.trim().slice(0,100) : '';
const valid = !!customer && !!message && !!requestId;
return [{json:{valid, customer, message, source, request_id:requestId, error:valid?'':'Required: customer, message, request_id'}}];

