const src = $('Validate input').first().json;
const raw = $input.first().json;
let a;
try { a = JSON.parse(raw.candidates[0].content.parts.map(p => p.text ?? "").join("")); } catch(e) { a = {}; }
const categories=['shipping','billing','security','general'];
const category = categories.includes(a.category) ? a.category : 'general';
const priority = a.priority === 'high' ? 'high' : 'normal';
const safe = x => typeof x === 'string' ? x.slice(0,600) : '';
const needs = priority === 'high' || category === 'security' || category === 'billing' || a.needs_human_review !== false;
return [{json:{...src,category,priority,needs_human_review:needs,summary:safe(a.summary)||src.message.slice(0,150),draft_reply:safe(a.draft_reply)||'Děkujeme, požadavek jsme přijali.',mode:'gemini-live'}}];

const items = $input.all();

return items.map(item => {
  const result = { ...item.json };

  const message = String(
    $('Validate input').first().json.message ?? ''
  ).toLowerCase();

  const securityPatterns = [
    /prolomil.{0,30}heslo/,
    /neoprávněn.{0,30}přístup/,
    /napaden.{0,30}účet/,
    /někdo.{0,30}přihlásil/,
    /hacked/,
    /account.{0,20}compromised/,
    /OVERRIDE.{0,80}compromised/,
    /nastav.{0,50}compromised/,
    /uprav.{0,50}compromised/
  ];

  const securityIncident = securityPatterns.some(
    pattern => pattern.test(message)
  );

  if (securityIncident) {
    result.category = 'security';
    result.priority = 'high';
    result.needs_human_review = true;
    result.security_override = true;
  } else {
    result.security_override = false;
  }

  return { json: result };
});
